package main

import (
	"flag"
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"io/ioutil"
	"log"
	"os"
)

type StructInfo struct {
	Name string // The name of the struct being parsed
}

func main() {
	var si StructInfo
	flag.StringVar(&si.Name, "name", "", "The name of the struct")
	flag.Parse()

	if len(si.Name) == 0 {
		log.Fatal("Please provide a valid struct name.")
	}

	src, err := ioutil.ReadFile(flag.Arg(1))
	if err != nil {
		log.Fatalf("Failed to read file: %v", err)
	}

	fset := token.NewFileSet()
	file, err := parser.ParseFile(fset, flag.Arg(1), src, parser.ParseComments)
	if err != nil {
		log.Fatalf("Failed to parse file: %v", err)
	}

	ast.Walk(func(node ast.Node) error {
		if node, ok := node.(*ast.Field); ok && node.Names[0].Name == si.Name {
			fmt.Printf("%s\n", node.Type.String())
			return nil
		}
		return nil
	})

	schema, _ := getAvroSchema(file, si.Name)
	schemaPath := fmt.Sprintf("./%s.avsc", si.Name)
	err = ioutil.WriteFile(schemaPath, []byte(schema), 0644)
	if err != nil {
		log.Fatalf("Failed to save schema: %v", err)
	}

	fmt.Println("Avro schema generated successfully at:", schemaPath)
}

// getAvroSchema returns the Avro schema definition for the given struct.
func getAvroSchema(tree *ast.File, structName string) (string, error) {
	// Implement your logic here to convert the Go struct into Avro schema
	// For simplicity, this example just prints out the field type.
	avroType := tree.Decls[len(tree.Decls)-1].(*ast.GenDecl).Specs[len(tree.Specs)-1]
	switch t := avroType.Value.(type) {
	case *ast.Object:
		for _, v := range t.Fields.List {
			if f, ok := v.(*ast.Field); ok {
				return f.Type.String(), nil
			}
		}
	default:
		return "", fmt.Errorf("Unsupported type: %T", t)
	}
	return "", nil
}
